script:
// Pranera CRM: makes "Convert to Deal" on the Lead page open the step-by-step wizard,
// when "Enable Convert to Deal Wizard" is ticked in CRM Settings. When it is off this
// script does nothing and CRM's own Convert to Deal button and dialog are used.
// Shipped as a fixture. A Form Script can add actions but has no API to remove CRM's
// own button, so the button is also hidden in the DOM (no change to the CRM app itself).
// The stock button is the only "Convert" button wrapped in CRM's Tooltip <div.inline-flex>;
// the action added below is a direct child of the header's button row.
function hideStockConvertButton() {
  if (window.__pranera_hide_convert) return
  window.__pranera_hide_convert = true

  const STOCK_LABEL = /^Convert( to Deal)?$/
  const hide = () => {
    if (!location.pathname.startsWith('/crm/leads/')) return
    document.querySelectorAll('div.inline-flex > button').forEach((button) => {
      if (STOCK_LABEL.test(button.textContent.trim())) button.parentElement.style.display = 'none'
    })
  }

  hide()
  // the header re-renders as the lead loads and when navigating between leads
  new MutationObserver(hide).observe(document.body, { childList: true, subtree: true })
}

async function setupForm({ doc, call }) {
  let enabled = false
  try {
    enabled = await call('pranera_crm.api.wizard_enabled')
  } catch (e) {
    // can't tell: fall back to CRM's own flow rather than hide its button
    enabled = false
  }
  if (!enabled) return {}

  hideStockConvertButton()

  return {
    actions: doc.converted
      ? []
      : [
          {
            label: 'Convert to Deal',
            onClick: () =>
              window.location.assign('/deal_wizard/' + encodeURIComponent(doc.name)),
          },
        ],
  }
}
